   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "A follow-me service will be implemented in the EIRENE network using the GSM Unstructured Supplementary Service Data (USSD) facility to allow users to establish and terminate the forwarding of calls from a functional number to their personal number.",
     "role": "statement"
    }
   ]
  },
