  {
   "id": "M1:T13",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'handover and cell selection' and asks about it."
  },
  {
   "id": "M1:T14",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Suitable algorithms will be tested and refined as necessary during the trials process.",
     "role": "statement"
    },
    {
     "text": "300ms represents our current best estimate of the QoS figure, although this will need to be confirmed through user trials.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T15",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'frequency band and channel arrangements' and asks about it."
  },
  {
   "id": "M1:T16",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The network shall operate in a sub-band, or combination of sub-bands, of the R-GSM band as defined in [EN 301 515, Index [35]].",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T17",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'termination of vgcs/vbs calls' and asks about it."
  },
  {
   "id": "M1:T18",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The network shall terminate the ongoing VGCS/VBS call if it receives the 3-digit sequence \"***\" transmitted via DTMF signals.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T19",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'muting and unmuting for vgcs calls' and asks about it."
  },
  {
   "id": "M1:T20",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The network shall send the SET-PARAMETER message with the attribute \"D-ATT = T\"1 [EN 301 515, Index [6]] to the mobile station of the talking subscriber if it receives the 3- digit sequence \"###\" transmitted via DTMF or the group call SETUP message2 from a controller terminal.",
     "role": "statement"
    },
    {
     "text": "When the network has detected the 3-digit DTMF sequence \"###\" transmitted via DTMF from a controller terminal and if the controller was not previously talking it should indicate its recognition by playing a single DTMF grant tone \"#\" of duration of 100ms ± 5ms to be sent to that controller terminal only.",
     "role": "statement"
    }
   ]
  }
 ]
